  "revision_action": "keep",
  "supportive_card_ids": ["C08","C25","C10","C19","C02","C03","C04","C29","C30","C09","C16","C17","C21","C28","C32","C27","C31"],
  "contradictory_card_ids": ["C01","C11","C13","C12","C05","C14","C22","C33","C35","C06","C07","C20","C23","C24","C26","C18"],
  "prediction_basis_card_ids": ["C08","C25","C10","C19","C02","C03","C04","C29","C30"],
  "claims": [
    {
      "claim": "The most transferable structural context, nilotinib (aminopyrimidine-aniline amide), has an assumed absolute oral bioavailability of about 31% in fasted humans (C08), repeated in L2 (C25); the L2 precipitation explanation (C34) does not provide a sub-20% value.",
      "card_ids": ["C08","C25","C34"]
    },
    {
      "claim": "GSK1322322, sharing the methoxy-aniline aminopyrimidine and basic amine motif, has absolute oral bioavailability of 57% fasted (C19) and 77% fed (C10), both above the 20% threshold.",
      "card_ids": ["C10","C19"]
    },
    {
      "claim": "Encainide, a methoxy-aniline/basic-amine context, has mean absolute oral bioavailability around 42% (C02, C04), 30 ± 7% (C03), and L2 42 ± 24% (C29, C30); although variable with some low patients (C18), the mean is above threshold.",
      "card_ids": ["C02","C03","C04","C18","C29","C30"]
    },
    {
      "claim": "Amiodarone, a low-transfer context, shows variable oral bioavailability mostly above 20% (22-86%, 35-50%, 20-55%, about 30%), so it does not contradict the positive direction.",
      "card_ids": ["C09","C16","C17","C21","C28","C32"]
    },
    {
      "claim": "Low-F contexts (prothipendyl C01, R101933 C11/C13, avoralstat C12, alprenolol C05/C14/C22/C33/C35, remimazolam C06/C07/C20/C23/C24/C26) are structurally dissimilar or low-transfer; L2 laniquidar records describe it as orally bioavailable (C27, C31), so these do not affirmatively establish query F < 20%.",
      "card_ids": ["C01","C11","C13","C12","C05","C14","C22","C33","C35","C06","C07","C20","C23","C24","C26","C27","C31"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for DA-8010, ramosetron, and dabigatran (C36-C47) report exposure without IV comparators or F values and are structurally dissimilar or low-applicability; they are neutral for the F >= 20% decision.",
      "card_ids": ["C36","C37","C38","C39","C40","C41","C42","C43","C44","C45","C46","C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C36","C37","C38","C39","C40","C41","C42","C43","C44","C45","C46","C47"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No human PK, dose, formulation, or prandial-state data are available for the query.",
    "No experimental permeability, solubility, efflux, or first-pass metabolism data are available for the query.",
    "L3 oral exposure records lack IV comparators and F values, so they cannot quantify bioavailability.",
    "The low neutral-fraction physicochemical prior is calculated, not experimentally confirmed, and could be offset by transporter-mediated absorption or high intrinsic permeability.",
    "No data address whether the acrylamide warhead or the basic diamine side chain alters absorption or first-pass extraction relative to the analogs."
  ],
  "decision_summary": "Predicted high because the most transferable structural contexts provide direct human absolute F values above 20% (nilotinib ~31% fasted; GSK1322322 57% fasted/77% fed; encainide mean ~42%), L2 reinforces these, and low-F contexts are structurally dissimilar or low-transfer; L3 oral exposure records are neutral (no F or IV comparator), and the physicochemical low-F prior is not affirmative endpoint evidence."
}

